import * as THREE from 'three';import {GLTFLoader} from './assets/GLTFLoader.js';
const canvas=document.getElementById('scene');let renderer;try{renderer=new THREE.WebGLRenderer({canvas,alpha:true,antialias:true})}catch{document.querySelector('.scene-label').textContent='3D weather requires WebGL';}
if(renderer){renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.3;const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(35,1,.1,100);camera.position.set(0,.5,8.9);camera.lookAt(0,-.25,0);scene.add(new THREE.HemisphereLight(0xe6f4ff,0x27476b,3));const light=new THREE.DirectionalLight(0xfff2d8,4);light.position.set(-3,5,5);scene.add(light);const rim=new THREE.DirectionalLight(0x8fcaff,3);rim.position.set(4,1,-2);scene.add(rim);let model,clouds=[],rain=[],sun;let rainy=false,snowy=false;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let scroll=0;addEventListener('scroll',()=>{scroll=window.scrollY},{passive:true});function sync(){const s=window.weatherState;if(!s||!model)return;rainy=s.code>=51;snowy=s.code>=71&&s.code<80;sun.visible=s.code<3;clouds.forEach(c=>{c.visible=s.code!==0;c.material.color.setHex(s.code>=3?0xa7bed7:0xd7e5f5)});rain.forEach(r=>{r.visible=rainy;r.material.color.setHex(snowy?0xffffff:0x5bbaed);r.scale.y=r.userData.scaleY*(snowy?.3:1)});}addEventListener('weatherchange',sync);new GLTFLoader().load('/assets/weather.glb',g=>{model=g.scene;scene.add(model);model.traverse(o=>{if(o.name.startsWith('Rain_')){o.userData.base=o.position.y;o.userData.scaleY=o.scale.y;rain.push(o)}if(o.name.startsWith('Cloud_'))clouds.push(o);if(o.name==='Sun')sun=o});sync()},undefined,()=>{document.querySelector('.scene-label').textContent='Weather scene could not load'});function resize(){const r=canvas.getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix()}new ResizeObserver(resize).observe(canvas);resize();let last=0;function frame(t){requestAnimationFrame(frame);if(document.hidden||t-last<32)return;last=t;const time=t*.001;if(model){model.rotation.y=reduced?-.12:Math.sin(time*.3)*.12+scroll*.0004;model.rotation.z=reduced?0:Math.sin(time*.4)*.025;model.position.y=reduced?0:Math.sin(time*.7)*.075-scroll*.00015;if(!reduced&&rainy)rain.forEach((r,i)=>{r.position.y=-.7-((time*(snowy?.35:1.8)+i*.127)%1.9)});}renderer.render(scene,camera)}requestAnimationFrame(frame);}
